function toast(message,undo){clearTimeout(toastTimer);const el=$('#toast');el.innerHTML=`<span>${esc(message)}</span>${undo?'<button id="undo">ย้อนกลับ</button>':''}`;el.classList.add('show');if(undo)$('#undo').onclick=undo;toastTimer=setTimeout(()=>el.classList.remove('show'),7000)}
// Web Locks serialize writes across tabs; compare the exact stored snapshot before mutation.
async function commit(message,fn,options={}){
 if(!globalThis.navigator?.locks){toast('เบราว์เซอร์นี้ไม่รองรับการบันทึกที่ปลอดภัย กรุณาใช้ Chrome ผ่าน localhost หรือ HTTPS');return false}
 return navigator.locks.request(KEY+'.write',()=>{
  if(recoveryRaw&&!options.replaceRecovery){toast('ข้อมูลเดิมผิดรูปแบบ กรุณาสำรองและนำเข้าไฟล์ที่ถูกต้องก่อน');return false}
  const actual=localStorage.getItem(KEY);
  if(actual!==storedRaw){
   try{const latest=actual?JSON.parse(actual):initial();validateBackup(latest);state=latest;storedRaw=actual;render()}catch{toast('ข้อมูลในอีกแท็บผิดรูปแบบ กรุณาสำรองข้อมูลก่อน');return false}
   toast('ข้อมูลถูกเปลี่ยนในอีกแท็บ กรุณาตรวจสอบแล้วบันทึกอีกครั้ง แบบร่างยังอยู่');return false
  }
  const before=structuredClone(state),beforeRaw=storedRaw,previousRecovery=recoveryRaw;
  try{
   fn();validateBackup(state);state.revision=(before.revision||0)+1;
   if(options.beforeImport&&beforeRaw)localStorage.setItem(KEY+'.before-import',beforeRaw);
   const nextRaw=JSON.stringify(state);localStorage.setItem(KEY,nextRaw);storedRaw=nextRaw;recoveryRaw=null;
   render();
   toast(message,async()=>{
    await navigator.locks.request(KEY+'.write',()=>{
     if(localStorage.getItem(KEY)!==nextRaw){toast('มีการเปลี่ยนแปลงใหม่แล้ว จึงย้อนกลับรายการนี้ไม่ได้');return}
     try{if(beforeRaw===null)localStorage.removeItem(KEY);else localStorage.setItem(KEY,beforeRaw);state=before;storedRaw=beforeRaw;recoveryRaw=previousRecovery;render();toast('ย้อนกลับแล้ว')}catch{toast('ย้อนกลับไม่สำเร็จ กรุณาสำรองข้อมูล')}
    })
   });return true
  }catch(err){
   state=before;recoveryRaw=previousRecovery;
   // Roll back a failed render only while holding the same cross-tab lock.
   try{if(storedRaw!==beforeRaw){if(beforeRaw===null)localStorage.removeItem(KEY);else localStorage.setItem(KEY,beforeRaw)}storedRaw=beforeRaw}catch{}
   try{render()}catch{}
   toast(err.name==='QuotaExceededError'?'พื้นที่จัดเก็บเต็ม กรุณาสำรองข้อมูลก่อน':'บันทึกไม่สำเร็จ: '+err.message);return false
  }
 });
}
