function filtered(){return state.logs.filter(l=>{if(projectFilter&&l.project!==projectFilter)return false;if(statusFilter&&l.status!==statusFilter)return false;if(priorityFilter&&l.priority!==priorityFilter)return false;if(fromDate&&l.date<fromDate)return false;if(toDate&&l.date>toDate)return false;if(period==='today'&&l.date!==today())return false;if(period==='yesterday'&&l.date!==addDays(today(),-1))return false;if(period==='week'&&(l.date<weekStart(today())||l.date>addDays(weekStart(today()),6)))return false;if(period==='month'&&!l.date?.startsWith(today().slice(0,7)))return false;if(period==='incomplete'&&['Done','Cancelled'].includes(l.status))return false;if(period==='done'&&l.status!=='Done')return false;if(search&&!JSON.stringify([l.task,l.project,l.description,l.reference_url,l.custom]).toLowerCase().includes(search.toLowerCase()))return false;return true}).sort((a,b)=>{const c=sort==='duration'?(Number(a.duration)||0)-(Number(b.duration)||0):String(a[sort]||'').localeCompare(String(b[sort]||''),'th');return(sortDesc?-c:c)||String(b.created_at).localeCompare(String(a.created_at))})}
