 document.body.classList.toggle('sidebar-collapsed',sidebarCollapsed);
 $$('[data-nav]').forEach(b=>b.onclick=()=>go(b.dataset.nav));$$('[data-add]').forEach(b=>b.onclick=()=>openLog());$$('[data-export]').forEach(b=>b.onclick=()=>go('export'));
