 if($('#restore-previous'))$('#restore-previous').onclick=async()=>{try{const raw=localStorage.getItem(KEY+'.before-import');if(!raw)throw Error('ไม่มีข้อมูลก่อนนำเข้า กรุณาใช้ไฟล์สำรองของคุณ');const previous=JSON.parse(raw);validateBackup(previous);await commit('กู้คืนข้อมูลแล้ว',()=>{state=previous},{replaceRecovery:true})}catch(e){toast(e.message)}};
