function syncNavigation(){if(!document.body)return;const mobile=window.innerWidth<=680,side=$('.sidebar'),visible=mobile?sidebarOpen:!sidebarCollapsed;side.classList.toggle('open',mobile&&sidebarOpen);side.hidden=!visible;side.inert=!visible||!!modal;side.setAttribute('aria-hidden',String(!visible||!!modal));$('.main').inert=!!modal||mobile&&sidebarOpen;$('.menu-toggle').setAttribute('aria-expanded',String(visible));$('.sidebar-scrim').hidden=!mobile||!sidebarOpen||!!modal}
