 const essential=state.fields.filter(f=>f.visible&&core.includes(f.id)),extras=state.fields.filter(f=>f.visible&&!core.includes(f.id));const ordered=state.fields.filter(f=>f.visible),extraBeforeCore=ordered.some((f,i)=>!core.includes(f.id)&&ordered.slice(i+1).some(x=>core.includes(x.id)));
 const fieldsHTML=extraBeforeCore?ordered.map(f=>fieldControl(f,values[f.id])).join(''):essential.map(f=>fieldControl(f,values[f.id])).join('');
