function calculateTime(){const start=$('#log-form #input-start_time')?.value,end=$('#log-form #input-end_time')?.value;if(start&&end&&$('#log-form #input-duration')){const mins=t=>Number(t.slice(0,2))*60+Number(t.slice(3));const diff=mins(end)-mins(start);if(diff>=0)$('#log-form #input-duration').value=diff}}
