function deleteLog(id){const l=state.logs.find(l=>l.id===id);if(confirm(`ต้องการลบงาน “${l.task}” หรือไม่?`))commit('ลบงานแล้ว',()=>{state.logs=state.logs.filter(l=>l.id!==id);page=Math.min(page,Math.max(1,Math.ceil(filtered().length/10)))})}
function exportExcel(){if(fromDate&&toDate&&fromDate>toDate){toast('วันที่สิ้นสุดต้องไม่น้อยกว่าวันที่เริ่ม');return}const logs=filtered();if(!logs.length){toast('ยังไม่มีข้อมูลให้ส่งออก');return}const standard=['date','user','project','task','description','status','priority','start_time','end_time','duration','reference_url','created_at','updated_at'];const headers=['Date','User','Project','Task','Description','Status','Priority','Start Time','End Time','Duration (minutes)','Reference','Created At','Updated At'];const fields=[...state.fields,...state.archivedFields].filter((f,i,a)=>!defaults().some(x=>x.id===f.id)&&a.findIndex(x=>x.id===f.id)===i);const rows=[[...headers,...fields.map(f=>f.label)],...logs.map(l=>[...standard.map(k=>l[k]??''),...fields.map(f=>l.custom?.[f.id]??'')])];const summary=[['Work Summary','Value'],['Total Tasks',logs.length],...statuses.map(s=>[s,logs.filter(l=>l.status===s).length]),['Total Hours',logs.reduce((a,l)=>a+(Number(l.duration)||0),0)/60],[],['Project','Tasks','Hours'],...[...new Set(logs.map(l=>l.project))].map(p=>{const ls=logs.filter(l=>l.project===p);return[p,ls.length,ls.reduce((a,l)=>a+(Number(l.duration)||0),0)/60]})];download(makeXlsx([{name:'Work Log',rows},{name:'Summary',rows:summary}]),`JoDJuM-${today()}.xlsx`);toast('ส่งออก Excel เรียบร้อยแล้ว')}
function bindSettings(){ $('#save-name').onclick=()=>{const name=$('#profile-name').value.trim();if(!name){toast('กรุณาระบุชื่อ');return}commit('บันทึกชื่อแล้ว',()=>state.name=name)};$('#backup').onclick=()=>{download(new Blob([JSON.stringify({...state,exported_at:new Date().toISOString()},null,2)],{type:'application/json'}),`JoDJuM-backup-${today()}.json`);toast('สำรองข้อมูลแล้ว')};$('#restore').onclick=()=>$('#backup-file').click();$('#backup-file').onchange=async e=>{try{const data=JSON.parse(await e.target.files[0].text());validateBackup(data);if(confirm(`แทนที่ข้อมูลปัจจุบันด้วยไฟล์สำรอง ${data.logs.length} งาน? ควรสำรองข้อมูลเดิมก่อน`)){await commit('นำเข้าข้อมูลสำเร็จ',()=>{state=data;settings=null},{beforeImport:true,replaceRecovery:true})}}catch(err){toast(err.message||'ไฟล์สำรองไม่ถูกต้อง')}};
 $('#add-field').onclick=()=>editField();$$('[data-field-edit]').forEach(b=>b.onclick=()=>editField(b.dataset.fieldEdit));$$('[data-visible]').forEach(b=>b.onclick=()=>{const f=settings.find(f=>f.id===b.dataset.visible);if(core.includes(f.id))return;f.visible=!f.visible;render()});$$('[data-move]').forEach(b=>b.onclick=()=>{const idx=settings.findIndex(f=>f.id===b.dataset.move);moveField(idx,idx+Number(b.dataset.direction))});let dragged;$$('[data-field]').forEach(el=>{el.ondragstart=e=>{if(e.target.closest('button,input')){e.preventDefault();return}dragged=el.dataset.field;el.classList.add('dragging');e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',dragged)};el.ondragend=()=>el.classList.remove('dragging');el.ondragover=e=>{e.preventDefault();e.dataTransfer.dropEffect='move'};el.ondrop=e=>{e.preventDefault();moveField(settings.findIndex(f=>f.id===dragged),settings.findIndex(f=>f.id===el.dataset.field))}});
 $('#save-settings').onclick=async()=>{const fields=structuredClone(settings);const saved=await commit('บันทึกการตั้งค่าฟอร์มแล้ว',()=>{const removed=state.fields.filter(f=>!fields.some(x=>x.id===f.id));state.archivedFields=[...state.archivedFields.filter(f=>!fields.some(x=>x.id===f.id)&&!removed.some(x=>x.id===f.id)),...removed];state.fields=fields.map((f,i)=>({...f,position:i,updated_at:new Date().toISOString()}))});if(saved){settings=structuredClone(state.fields);render()}};$('#discard-settings').onclick=()=>{settings=structuredClone(state.fields);render()};$('#reset-form').onclick=()=>{if(confirm('คืนค่าฟอร์มเริ่มต้น? ข้อมูลงานเดิมและค่าฟิลด์เก่าจะยังอยู่')){settings=defaults();render();toast('คืนค่าฟอร์มแล้ว กดบันทึกฟอร์มเพื่อใช้งาน')}} }
function moveField(from,to){if(from<0||to<0||to>=settings.length)return;const [f]=settings.splice(from,1);settings.splice(to,0,f);settings.forEach((f,i)=>f.position=i);render()}
function editField(id){const f=settings.find(f=>f.id===id)||{id:'custom_'+uid(),label:'',type:'Text',visible:true,required:false,default:'',placeholder:'',options:[],created_at:new Date().toISOString()},locked=core.includes(f.id),builtIn=defaults().some(x=>x.id===f.id);modal={kind:'field'};showModal(id?'ตั้งค่าฟิลด์':'เพิ่มฟิลด์ใหม่','ปรับให้เข้ากับข้อมูลที่คุณต้องการจด',`<form id="field-form" class="modal-body"><div id="field-error" role="alert"></div><div class="field"><label for="field-label">ชื่อฟิลด์ <span>*</span></label><input id="field-label" value="${esc(f.label)}" required></div><div class="field"><label for="field-type">ประเภท</label><select id="field-type" ${builtIn?'disabled':''}>${selectOptions(types,f.type)}</select>${builtIn?'<small>ประเภทของฟิลด์มาตรฐานคงไว้เพื่อให้รายงานถูกต้อง</small>':''}</div><div class="field"><label for="field-options">ตัวเลือก (หนึ่งค่าต่อบรรทัด)</label><textarea id="field-options" ${builtIn?'disabled':''}>${esc(f.options.join('\n'))}</textarea><small>ใช้กับ Dropdown, Multi Select และ Radio</small></div><div class="field"><label for="field-default">ค่าเริ่มต้น</label><input id="field-default" value="${esc(Array.isArray(f.default)?f.default.join(', '):f.default)}"><small>Date ใช้ today ได้ · Multi Select แยกค่าด้วย , · Checkbox ใช้ true หรือ false</small></div><div class="field"><label for="field-placeholder">Placeholder</label><input id="field-placeholder" value="${esc(f.placeholder)}"></div><label class="switch-line"><input type="checkbox" id="field-required" ${f.required?'checked':''} ${locked?'disabled':''}>จำเป็นต้องกรอก</label><label class="switch-line"><input type="checkbox" id="field-visible" ${f.visible?'checked':''} ${locked?'disabled':''}>แสดงในฟอร์ม</label>${!locked&&id?'<button type="button" class="danger" id="delete-field">'+icon('trash')+'ลบฟิลด์นี้</button>':''}</form>`,'<button id="cancel-field">ยกเลิก</button><button class="primary" type="submit" form="field-form">ใช้การตั้งค่า</button>');$('#cancel-field').onclick=closeModal;$('#field-form').onsubmit=e=>{e.preventDefault();const type=$('#field-type').value,options=[...new Set($('#field-options').value.split('\n').map(v=>v.trim()).filter(Boolean))];let def=$('#field-default').value.trim(),err='';if(['Dropdown','Multi Select','Radio'].includes(type)&&!options.length&&!builtIn)err='กรุณาเพิ่มตัวเลือกอย่างน้อยหนึ่งค่า';if(type==='Multi Select')def=def?def.split(',').map(v=>v.trim()):[];if(type==='Checkbox'){if(!['','true','false'].includes(def))err='ค่าเริ่มต้น Checkbox ต้องเป็น true หรือ false';def=def==='true'}if(['Number','Duration'].includes(type)&&def!==''){def=Number(def);if(!Number.isFinite(def)||type==='Duration'&&def<0)err='กรุณากรอกค่าเริ่มต้นเป็นตัวเลขที่ถูกต้อง'}const opts=f.id==='project'?state.projects:builtIn?f.options:options;if(['Dropdown','Radio'].includes(type)&&def&&!opts.includes(def))err='ค่าเริ่มต้นต้องอยู่ในรายการตัวเลือก';if(type==='Multi Select'&&def.some(v=>!opts.includes(v)))err='ค่าเริ่มต้นต้องอยู่ในรายการตัวเลือก';if(type==='Date'&&def&&def!=='today'&&!/^\d{4}-\d{2}-\d{2}$/.test(def))err='ค่าเริ่มต้นวันที่ใช้ YYYY-MM-DD หรือ today';if(err){$('#field-error').innerHTML=`<div class="error">${err}</div>`;return}const updated={...f,label:$('#field-label').value.trim(),type,options:builtIn?f.options:options,default:def,placeholder:$('#field-placeholder').value,required:locked||$('#field-required').checked,visible:locked||$('#field-visible').checked,updated_at:new Date().toISOString()};if(!updated.label)return;const proposed=id?settings.map(x=>x.id===id?updated:x):[...settings,updated];try{validateBackup({...state,fields:proposed})}catch(error){$('#field-error').innerHTML=`<div class="error">${esc(error.message)}</div>`;return}settings=proposed;closeModal();render()};if($('#delete-field'))$('#delete-field').onclick=()=>{const used=state.logs.some(l=>getValue(l,id)!==undefined);if(confirm(used?'ฟิลด์นี้มีข้อมูลที่บันทึกไว้แล้ว การลบจะหยุดการกรอกใหม่ แต่ข้อมูลเก่าจะไม่ถูกลบ ต้องการลบฟิลด์?':'ต้องการลบฟิลด์นี้จากฟอร์ม?')){settings=settings.filter(x=>x.id!==id);closeModal();render()}}}
function validDate(value){if(typeof value!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(value))return false;const date=new Date(value+'T12:00:00Z');return !Number.isNaN(date.getTime())&&date.toISOString().slice(0,10)===value}
function validTime(value){return typeof value==='string'&&/^([01]\d|2[0-3]):[0-5]\d$/.test(value)}
function validUrl(value){try{return ['https:','http:'].includes(new URL(value).protocol)}catch{return false}}
function validateBackup(data){
 const object=v=>v!==null&&typeof v==='object'&&!Array.isArray(v);
 const scalar=v=>typeof v==='string'||typeof v==='boolean'||typeof v==='number'&&Number.isFinite(v);
 const optional=(v,check)=>v===undefined||v===''||check(v);
 const fail=message=>{throw Error(message)};
 if(!object(data)||data.version!==1||!Array.isArray(data.logs)||!Array.isArray(data.fields)||!Array.isArray(data.projects)||!Array.isArray(data.archivedFields)||typeof data.name!=='string')fail('ไฟล์นี้ไม่ใช่ข้อมูลสำรอง JoDJuM');
 if(data.revision!==undefined&&!(Number.isSafeInteger(data.revision)&&data.revision>=0))fail('Revision ของข้อมูลไม่ถูกต้อง');
 if(!data.projects.length||!data.projects.every(p=>typeof p==='string'&&p.trim())||new Set(data.projects).size!==data.projects.length)fail('ข้อมูลโปรเจกต์ไม่ถูกต้อง');
 const standard=defaults(),known=new Map(standard.map(f=>[f.id,f]));
 for(const id of core){const f=data.fields.find(f=>f?.id===id);if(!f||f.visible!==true||f.required!==true||f.type!==known.get(id).type)fail('ไฟล์สำรองไม่มีฟิลด์หลักที่ถูกต้อง')}
 const all=[...data.fields,...data.archivedFields],ids=new Set();
 for(const f of all){
  if(!object(f)||typeof f.id!=='string'||!(known.has(f.id)||/^custom_[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/.test(f.id))||typeof f.label!=='string'||!f.label.trim()||!types.includes(f.type)||!Array.isArray(f.options)||!f.options.every(o=>typeof o==='string'&&o.trim())||new Set(f.options).size!==f.options.length)fail('โครงสร้างฟิลด์ในไฟล์ไม่ถูกต้อง');
  if(typeof f.visible!=='boolean'||typeof f.required!=='boolean'||!optional(f.placeholder,v=>typeof v==='string'))fail('การตั้งค่าฟิลด์ไม่ถูกต้อง');
  if(known.has(f.id)&&f.type!==known.get(f.id).type)fail('ประเภทฟิลด์มาตรฐานไม่ถูกต้อง');
  if(['status','priority'].includes(f.id)){const expected=known.get(f.id).options;if(f.options.length!==expected.length||!expected.every(x=>f.options.includes(x)))fail('ตัวเลือกสถานะหรือความสำคัญไม่ถูกต้อง')}
  if(['Dropdown','Radio','Multi Select'].includes(f.type)&&f.id!=='project'&&!f.options.length)fail('ฟิลด์ตัวเลือกไม่มีรายการ');
  const d=f.default,opts=f.id==='project'?data.projects:f.options;
  if(d!==undefined&&d!==''){
   if(f.type==='Date'&&d!=='today'&&!validDate(d)||f.type==='Time'&&!validTime(d)||f.type==='Date & Time'&&!(typeof d==='string'&&validDate(d.slice(0,10))&&d[10]==='T'&&validTime(d.slice(11))))fail('ค่าเริ่มต้นวันที่หรือเวลาไม่ถูกต้อง');
   if(['Number','Duration'].includes(f.type)&&!(typeof d==='number'&&Number.isFinite(d)&& (f.type!=='Duration'||Number.isInteger(d)&&d>=0)))fail('ค่าเริ่มต้นตัวเลขไม่ถูกต้อง');
   if(f.type==='Checkbox'&&typeof d!=='boolean'||['Text','Long Text','URL'].includes(f.type)&&typeof d!=='string')fail('ชนิดค่าเริ่มต้นไม่ถูกต้อง');
   if(f.type==='URL'&&!validUrl(d))fail('ค่าเริ่มต้นลิงก์ไม่ถูกต้อง');
   if(['Dropdown','Radio'].includes(f.type)&&!opts.includes(d)||f.type==='Multi Select'&&!(Array.isArray(d)&&d.every(x=>opts.includes(x))))fail('ค่าเริ่มต้นไม่อยู่ในตัวเลือก');
  }
 }
 for(const f of data.fields){if(ids.has(f.id))fail('ฟิลด์ซ้ำในไฟล์');ids.add(f.id)}
 const logIds=new Set();
 for(const l of data.logs){
  if(!object(l)||typeof l.id!=='string'||!/^([a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12})$/.test(l.id)||logIds.has(l.id)||typeof l.task!=='string'||!l.task.trim()||!validDate(l.date)||!statuses.includes(l.status)||!data.projects.includes(l.project))fail('ข้อมูลบันทึกงานในไฟล์ไม่ถูกต้อง');logIds.add(l.id);
  if(!optional(l.duration,v=>typeof v==='number'&&Number.isFinite(v)&&Number.isInteger(v)&&v>=0)||!optional(l.start_time,validTime)||!optional(l.end_time,validTime)||l.start_time&&l.end_time&&l.start_time>l.end_time)fail('เวลาหรือระยะเวลาของงานไม่ถูกต้อง');
  for(const id of ['user','description','reference_url','priority','created_at','updated_at'])if(!optional(l[id],v=>typeof v==='string'))fail('ชนิดข้อมูลบันทึกงานไม่ถูกต้อง');
  if(l.reference_url&&!validUrl(l.reference_url))fail('ลิงก์ของงานไม่ถูกต้อง');
  if(l.priority&&!['Low','Medium','High','Urgent'].includes(l.priority))fail('ความสำคัญของงานไม่ถูกต้อง');
  if(l.custom!==undefined&&(!object(l.custom)||!Object.values(l.custom).every(v=>scalar(v)||Array.isArray(v)&&v.every(scalar))))fail('ค่าฟิลด์เพิ่มเติมไม่ถูกต้อง');
 }
}
function loadDemo(){if(state.logs.length)return;const d=today(),tasks=[['ทดสอบ Chatbot และตรวจสอบคำตอบ','efinAI','Done',90,'High'],['อัปเดต Requirement สำหรับหน้า Dashboard','efinAI','Done',60,'Medium'],['Review API สำหรับระบบรายงาน','Better Trade','In Progress',120,'High'],['ประชุม Daily sync กับทีม','Internal','Done',30,'Medium'],['เตรียมสรุปผลการทดสอบประจำสัปดาห์','efinAI','To Do',0,'Medium']];commit('แสดงข้อมูลตัวอย่างแล้ว',()=>{state.demo=true;const now=new Date().toISOString();state.logs=tasks.map(([task,project,status,duration,priority])=>({id:uid(),user_id:'local',user:'ผู้ใช้ตัวอย่าง',date:d,task,project,status,duration,priority,description:'ข้อมูลตัวอย่างสำหรับทดลองใช้งาน JoDJuM',custom:{},created_at:now,updated_at:now,demo:true}));for(let i=1;i<=5;i++)state.logs.push({id:uid(),user_id:'local',user:'ผู้ใช้ตัวอย่าง',date:addDays(d,-i),task:['ตรวจสอบผล QA และบันทึกข้อเสนอแนะ','ออกแบบ flow สำหรับหน้า Work Log','วางแผน Sprint และจัดลำดับงาน'][i%3],project:state.projects[i%3],status:'Done',duration:120+i*30,priority:'Medium',custom:{},created_at:now,updated_at:now,demo:true})})}
render();
